}

.textfield {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  width: 100%;
  font-family: inherit;
}

.textfield__label {
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.3;
  color: var(--myelin-tf-label);
  cursor: pointer;
}

.textfield__input {
  box-sizing: border-box;
  width: 100%;
  min-height: 2.5rem;
  padding: 0.5rem 0.75rem;
  font: inherit;
  font-size: 1rem;
  line-height: 1.4;
