  border-radius: 0.5rem;
  outline: none;
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.textfield__input::placeholder {
  color: var(--myelin-tf-placeholder);
  opacity: 1;
}

.textfield__input:hover {
  border-color: var(--myelin-tf-border-hover);
}

.textfield__input:focus-visible {
  border-color: var(--myelin-tf-focus);
  box-shadow: 0 0 0 3px var(--myelin-tf-focus-ring);
}

.textfield--error .textfield__input,
.textfield__input[aria-invalid="true"] {
  border-color: var(--myelin-tf-error);
}

.textfield--error .textfield__input:focus-visible,
.textfield__input[aria-invalid="true"]:focus-visible {
  border-color: var(--myelin-tf-error);
  box-shadow: 0 0 0 3px var(--myelin-tf-error-ring);
}

.textfield__error {
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.4;
  color: var(--myelin-tf-error);
}

@media (prefers-reduced-motion: reduce) {
  .textfield__input {
    transition: none;
  }
}
